WITH eligible AS (
 SELECT player_fifa_api_id, date, overall_rating,
        ROW_NUMBER() OVER (PARTITION BY player_fifa_api_id ORDER BY date DESC, id DESC) rn
 FROM Player_Attributes
 WHERE date <= '2013-07-12' AND defensive_work_rate IN ('low','medium','high')
), current_ratings AS (
 SELECT player_fifa_api_id, overall_rating FROM eligible WHERE rn=1
), avg_rating AS (
 SELECT AVG(overall_rating) avg_overall FROM current_ratings
), donovan AS (
 SELECT MAX(c.overall_rating) rating FROM current_ratings c JOIN Player p ON p.player_fifa_api_id=c.player_fifa_api_id WHERE p.player_name='Landon Donovan'
)
SELECT ROUND(100.0 * (donovan.rating-avg_rating.avg_overall)/avg_rating.avg_overall, 2) AS percentage_higher FROM donovan, avg_rating

